N = 9
X = [5, 3, 7, 1, 9, 8, 2, 6, 4]

def verify(witness):
    n = witness['n']
    x = witness['permutation']
    if n != N:
        raise ValueError('n mismatch')
    if not isinstance(x, list) or len(x) != N:
        raise ValueError('length mismatch')
    if sorted(x) != list(range(1, N + 1)):
        raise ValueError('not a permutation of [n]')
    pos = [0] * (N + 1)
    for i in range(N):
        v = x[i]
        if not (1 <= v <= N) or pos[v] != 0:
            raise ValueError('malformed value')
        pos[v] = i
    checked = 0
    for a in range(1, N + 1):
        for d in range(1, (N - 1) // 3 + 1):
            if a + 3 * d > N:
                continue
            p0 = pos[a]
            p1 = pos[a + d]
            p2 = pos[a + 2 * d]
            p3 = pos[a + 3 * d]
            checked += 1
            if p0 < p1 and p1 < p2 and p2 < p3:
                raise ValueError('monotone 4-AP, increasing indices')
            if p0 > p1 and p1 > p2 and p2 > p3:
                raise ValueError('monotone 4-AP, decreasing indices')
    if checked != 9:
        raise ValueError('coverage mismatch')

witness = {'n': N, 'permutation': X}
try:
    verify(witness)
except Exception:
    raise SystemExit(1)
raise SystemExit(0)
